package com.lyrashop.audit.service;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import com.lyrashop.audit.dto.AdminAuditLogResponse;import com.lyrashop.audit.entity.AdminAuditLog;import com.lyrashop.audit.repository.AdminAuditLogRepository;@Service public class AdminAuditService{private final AdminAuditLogRepository logs;public AdminAuditService(AdminAuditLogRepository logs){this.logs=logs;}@Transactional public void record(UUID adminId,String method,String path,int status,String ip,String agent){String[] parts=path.replaceFirst("^/api/v1/admin/?","").split("/");String resource=parts.length>0?parts[0]:"admin";String resourceId=parts.length>1&&parts[1].matches("[0-9a-fA-F-]{8,}|\\d+")?parts[1]:null;String action=action(method,parts);logs.save(new AdminAuditLog(adminId,method,action,resource,resourceId,path,status,limit(ip,64),limit(agent,500)));}@Transactional(readOnly=true)public List<AdminAuditLogResponse> list(){return logs.findTop200ByOrderByCreatedAtDescIdDesc().stream().map(AdminAuditLogResponse::from).toList();}@Transactional(readOnly=true)public Page<AdminAuditLogResponse> page(String query,String action,Integer responseStatus,Pageable pageable){Specification<AdminAuditLog> specification=(root,ignored,builder)->builder.conjunction();if(query!=null&&!query.isBlank()){String pattern="%"+query.strip().toLowerCase(Locale.ROOT)+"%";specification=specification.and((root,ignored,builder)->builder.or(builder.like(builder.lower(root.get("path")),pattern),builder.like(builder.lower(root.get("resourceType")),pattern),builder.like(builder.lower(root.get("resourceId")),pattern)));}if(action!=null&&!action.isBlank())specification=specification.and((root,ignored,builder)->builder.equal(root.get("action"),action));if(responseStatus!=null)specification=specification.and((root,ignored,builder)->builder.equal(root.get("responseStatus"),responseStatus));return logs.findAll(specification,pageable).map(AdminAuditLogResponse::from);}private static String action(String method,String[] parts){String suffix=parts.length==0?"":parts[parts.length-1].replace('-','_').toUpperCase(Locale.ROOT);if(Set.of("activate","deactivate","status","role","cancel","approve","reject","receive","moderation","read","read_all").contains(suffix.toLowerCase(Locale.ROOT)))return suffix;return switch(method){case "POST"->"CREATE";case "DELETE"->"DELETE";case "PATCH","PUT"->"UPDATE";default->method;};}private static String limit(String v,int n){return v==null?null:v.substring(0,Math.min(v.length(),n));}}
